Source code in <code>streamdaq/computations/numeric.py</code> <pre><code>def filter_numeric(
    elements: Iterable[Any],
    *,
    allow_nan: bool = False,
    allow_inf: bool = False,
) -&gt; list[float]:
    elements = ensure_iterable(elements)
    result: list[float] = []
    for element in elements:
        if isinstance(element, (bool, np.bool_)):
            continue
        try:
            value = float(element)
        except (ValueError, TypeError):
            continue
        if not allow_nan and math.isnan(value):
            continue
        if not allow_inf and math.isinf(value):
            continue
        result.append(value)
    return result
</code></pre>

Source code in <code>streamdaq/computations/numeric.py</code> <pre><code>def first_digit(elements: Iterable[int | float]) -&gt; list[int]:
    elements = ensure_iterable(elements)
    result = []
    for number in elements:
        if not np.isfinite(number):
            raise ValueError(f"Cannot extract first digit from {number}")
        if number == 0:
            result.append(0)
        else:
            result.append(int(f"{abs(number):.15e}"[0]))
    return result
</code></pre>

Source code in <code>streamdaq/computations/numeric.py</code> <pre><code>def fraction(
    numerator: int | float,
    denominator: int | float,
    precision: int | None = None,
) -&gt; float:
    if denominator == 0:
        raise ZeroDivisionError("denominator must not be zero")
    result = numerator / denominator
    if precision is None:
        return result
    return round(result, precision)
</code></pre>

